package io.github.tukiza7_debug.vibecast.addonx.analyzer

/**
 * Stable, valid applicationId for site APKs generated by AddOnX.
 *
 * Android applicationId rules: at least two segments separated by dots, every
 * segment matches [a-zA-Z0-9_], and a segment must not start with a digit. The
 * suffix derives from the app name via an unsigned 32-bit hash rendered in base36
 * (never negative - [kotlin.math.abs] keeps [Int.MIN_VALUE] negative), so two
 * names rarely collide and the same name always maps to the same id.
 */
object SitePackageId {
    private const val PREFIX = "io.github.vibecast.site"

    fun forAppName(appName: String): String {
        val slug =
            appName
                .lowercase()
                .map { if (it in 'a'..'z' || it in '0'..'9') it else '_' }
                .joinToString("")
                .trim('_')
                .take(24)
                .trim('_')
        val safeSlug =
            when {
                slug.isEmpty() -> "site"
                slug.first().isDigit() -> "s$slug"
                else -> slug
            }
        val suffix = (appName.hashCode().toLong() and 0xffffffffL).toString(36)
        return "$PREFIX.${safeSlug}_$suffix"
    }
}
